import pandas as pd, numpy as np
for eid in [1,3,5,6]:
    try:
        df = pd.read_csv(eval(f"experiment_{eid}_csv"))
        print(f"=== exp {eid} n={len(df)} cols={list(df.columns)}")
        print(df.describe().round(2).T[['mean','std','min','max']])
        print("corr with WaferYield:")
        if 'WaferYield' in df.columns:
            print(df.corr(numeric_only=True)['WaferYield'].round(3))
    except Exception as e:
        print(eid, "err", e)

